/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super(classStr(AVACloseTraverseService), methodStr(AVACloseTraverseService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// construct method of class
/// </summary>
/// <param name = "_executionMode">SysOperationExecutionMode, default SysOperationExecutionMode::Synchronous</param>
/// <returns>AVACloseTraverseController</returns>
public static AVACloseTraverseController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACloseTraverseController controller;
    controller = new AVACloseTraverseController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVATraverseTrans   travTrans = _args.record();
    AVACloseTraverseController controller;
    AVACloseTraverseContract   contract;
    controller = AVACloseTraverseController::construct();
    contract = controller.getDataContractObject();
    contract.parmTraverseNum(travTrans.TravNum);
    controller.parmArgs(_args);
    controller.startOperation();
}
